import{_ as s,o as a,c as n,ag as r}from"./chunks/framework.CAXxHpAX.js";const c=JSON.parse('{"title":"06 应用层","description":"","frontmatter":{},"headers":[],"relativePath":"计算机网络/06_应用层.md","filePath":"计算机网络/06_应用层.md","lastUpdated":1777091574000}'),l={name:"计算机网络/06_应用层.md"};function e(o,t,i,d,p,g){return a(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="_06-应用层" tabindex="-1">06 应用层 <a class="header-anchor" href="#_06-应用层" aria-label="Permalink to &quot;06 应用层&quot;">​</a></h1><blockquote><p>本章涵盖常用应用层协议。以选择题为主，需要记忆各协议使用的端口号和传输层协议。</p></blockquote><h2 id="一、dns-域名系统" tabindex="-1">一、DNS（域名系统） <a class="header-anchor" href="#一、dns-域名系统" aria-label="Permalink to &quot;一、DNS（域名系统）&quot;">​</a></h2><h3 id="_1-1-功能与特点" tabindex="-1">1.1 功能与特点 <a class="header-anchor" href="#_1-1-功能与特点" aria-label="Permalink to &quot;1.1 功能与特点&quot;">​</a></h3><ul><li>功能：<strong>域名 → IP 地址</strong>的映射（域名解析）</li><li>使用 <strong>UDP</strong>，端口号 <strong>53</strong>（大量数据时也可用 TCP）</li><li>采用<strong>分布式层次数据库</strong></li></ul><h3 id="_1-2-域名结构" tabindex="-1">1.2 域名结构 <a class="header-anchor" href="#_1-2-域名结构" aria-label="Permalink to &quot;1.2 域名结构&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主机名.三级域名.二级域名.顶级域名</span></span>
<span class="line"><span>例：www.example.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>顶级域名分类：国家顶级域名（.cn/.us）、通用顶级域名（.com/.org/.edu）</p><h3 id="_1-3-dns-服务器层次" tabindex="-1">1.3 DNS 服务器层次 <a class="header-anchor" href="#_1-3-dns-服务器层次" aria-label="Permalink to &quot;1.3 DNS 服务器层次&quot;">​</a></h3><ul><li><strong>根域名服务器</strong>：全球 13 组</li><li><strong>顶级域名服务器</strong>：管理各顶级域名</li><li><strong>权威域名服务器</strong>：管理区域内的域名映射</li><li><strong>本地域名服务器</strong>：ISP 提供，不属于层次结构</li></ul><h3 id="_1-4-域名解析过程" tabindex="-1">1.4 域名解析过程 <a class="header-anchor" href="#_1-4-域名解析过程" aria-label="Permalink to &quot;1.4 域名解析过程&quot;">​</a></h3><ol><li>主机先查<strong>本地 DNS 缓存</strong></li><li>向<strong>本地域名服务器</strong>发送查询</li><li>本地域名服务器执行： <ul><li><strong>递归查询</strong>：代替主机向上级服务器查询（一般主机→本地DNS用递归）</li><li><strong>迭代查询</strong>：返回下一个应查询的服务器地址（一般DNS服务器之间用迭代）</li></ul></li></ol><h2 id="二、ftp-文件传输协议" tabindex="-1">二、FTP（文件传输协议） <a class="header-anchor" href="#二、ftp-文件传输协议" aria-label="Permalink to &quot;二、FTP（文件传输协议）&quot;">​</a></h2><ul><li>使用 <strong>TCP</strong></li><li><strong>两个连接</strong>：控制连接（端口 <strong>21</strong>，始终保持）+ 数据连接（端口 <strong>20</strong>）</li><li>两种模式：主动模式（PORT）/ 被动模式（PASV）</li><li>客户端和服务器都需要建立两个进程</li></ul><h2 id="三、电子邮件" tabindex="-1">三、电子邮件 <a class="header-anchor" href="#三、电子邮件" aria-label="Permalink to &quot;三、电子邮件&quot;">​</a></h2><h3 id="_3-1-邮件系统组成" tabindex="-1">3.1 邮件系统组成 <a class="header-anchor" href="#_3-1-邮件系统组成" aria-label="Permalink to &quot;3.1 邮件系统组成&quot;">​</a></h3><p>用户代理 → MTA（发送方邮件服务器）→ MTA（接收方邮件服务器）→ 用户代理</p><h3 id="_3-2-相关协议" tabindex="-1">3.2 相关协议 <a class="header-anchor" href="#_3-2-相关协议" aria-label="Permalink to &quot;3.2 相关协议&quot;">​</a></h3><table tabindex="0"><thead><tr><th>协议</th><th>功能</th><th>传输层</th><th>端口</th></tr></thead><tbody><tr><td><strong>SMTP</strong></td><td><strong>发送</strong>邮件</td><td>TCP</td><td><strong>25</strong></td></tr><tr><td><strong>POP3</strong></td><td><strong>接收</strong>邮件（下载后删除/保留）</td><td>TCP</td><td><strong>110</strong></td></tr><tr><td><strong>IMAP</strong></td><td><strong>接收</strong>邮件（在服务器上管理）</td><td>TCP</td><td><strong>143</strong></td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">SMTP 只能传送 ASCII 文本</p><p>非 ASCII 数据（附件、图片等）需要通过 <strong>MIME 扩展</strong>进行编码。</p></div><h3 id="_3-3-邮件发送过程" tabindex="-1">3.3 邮件发送过程 <a class="header-anchor" href="#_3-3-邮件发送过程" aria-label="Permalink to &quot;3.3 邮件发送过程&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发送方UA --SMTP--&gt; 发送方邮件服务器 --SMTP--&gt; 接收方邮件服务器 --POP3/IMAP--&gt; 接收方UA</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="四、http-超文本传输协议" tabindex="-1">四、HTTP（超文本传输协议） <a class="header-anchor" href="#四、http-超文本传输协议" aria-label="Permalink to &quot;四、HTTP（超文本传输协议）&quot;">​</a></h2><h3 id="_4-1-基本特点" tabindex="-1">4.1 基本特点 <a class="header-anchor" href="#_4-1-基本特点" aria-label="Permalink to &quot;4.1 基本特点&quot;">​</a></h3><ul><li>使用 <strong>TCP</strong>，端口号 <strong>80</strong>（HTTPS 为 <strong>443</strong>）</li><li><strong>无状态</strong>协议（使用 Cookie 维持状态）</li><li>HTTP/1.0：非持久连接（每个请求一个 TCP 连接）</li><li>HTTP/1.1：<strong>持久连接</strong>（默认，一个 TCP 连接可传送多个请求） <ul><li>非流水线方式：收到响应后才发下一个请求</li><li><strong>流水线方式</strong>：不等响应就连续发送请求</li></ul></li></ul><h3 id="_4-2-http-报文" tabindex="-1">4.2 HTTP 报文 <a class="header-anchor" href="#_4-2-http-报文" aria-label="Permalink to &quot;4.2 HTTP 报文&quot;">​</a></h3><p><strong>请求报文</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求行：方法 URL 版本（如 GET /index.html HTTP/1.1）</span></span>
<span class="line"><span>首部行：Host: www.example.com</span></span>
<span class="line"><span>        Connection: keep-alive</span></span>
<span class="line"><span>空行</span></span>
<span class="line"><span>实体主体（POST 方法使用）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>常用方法：<strong>GET</strong>（获取）、<strong>POST</strong>（提交）、PUT（更新）、DELETE（删除）、HEAD（获取首部）</p><p><strong>响应报文</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>状态行：版本 状态码 短语（如 HTTP/1.1 200 OK）</span></span>
<span class="line"><span>首部行</span></span>
<span class="line"><span>空行</span></span>
<span class="line"><span>实体主体</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_4-3-http-状态码" tabindex="-1">4.3 HTTP 状态码 <a class="header-anchor" href="#_4-3-http-状态码" aria-label="Permalink to &quot;4.3 HTTP 状态码&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态码</th><th>类别</th><th>常见值</th></tr></thead><tbody><tr><td>1xx</td><td>信息</td><td>100 Continue</td></tr><tr><td><strong>2xx</strong></td><td><strong>成功</strong></td><td><strong>200 OK</strong></td></tr><tr><td>3xx</td><td>重定向</td><td>301 永久移动, 302 临时移动</td></tr><tr><td><strong>4xx</strong></td><td><strong>客户端错误</strong></td><td><strong>404 Not Found</strong>, 403 Forbidden</td></tr><tr><td><strong>5xx</strong></td><td><strong>服务器错误</strong></td><td><strong>500 Internal Server Error</strong></td></tr></tbody></table><h3 id="_4-4-https" tabindex="-1">4.4 HTTPS <a class="header-anchor" href="#_4-4-https" aria-label="Permalink to &quot;4.4 HTTPS&quot;">​</a></h3><ul><li>HTTP + <strong>SSL/TLS</strong> 加密</li><li>端口号 <strong>443</strong></li><li>对称加密传输数据 + 非对称加密交换密钥 + CA 证书验证身份</li></ul><h2 id="五、dhcp-动态主机配置协议" tabindex="-1">五、DHCP（动态主机配置协议） <a class="header-anchor" href="#五、dhcp-动态主机配置协议" aria-label="Permalink to &quot;五、DHCP（动态主机配置协议）&quot;">​</a></h2><ul><li>使用 <strong>UDP</strong>，客户端 68，服务器 67</li><li>四步过程：<strong>Discover</strong> → <strong>Offer</strong> → <strong>Request</strong> → <strong>ACK</strong></li><li>全部使用<strong>广播</strong>方式</li><li>分配的 IP 地址有<strong>租约期限</strong></li></ul><h2 id="六、输入-url-后的完整过程-综合题" tabindex="-1">六、输入 URL 后的完整过程（综合题） <a class="header-anchor" href="#六、输入-url-后的完整过程-综合题" aria-label="Permalink to &quot;六、输入 URL 后的完整过程（综合题）&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">跨章节综合考点</p><p>此过程贯穿应用层→传输层→网络层→数据链路层→物理层，是理解网络协作的核心。</p></div><ol><li><strong>DNS 解析</strong>：浏览器缓存 → 本地 hosts → 本地 DNS 服务器 → 递归/迭代查询 → 获得 IP</li><li><strong>TCP 三次握手</strong>：与目标 IP 的 80/443 端口建立连接</li><li><strong>发送 HTTP 请求</strong>：构造请求报文（GET /index.html HTTP/1.1）</li><li><strong>网络层封装</strong>：加上 IP 首部（源/目的 IP），查路由表确定下一跳</li><li><strong>ARP 解析</strong>：若下一跳 MAC 未知，ARP 广播获取</li><li><strong>数据链路层封装</strong>：加上 MAC 帧首部尾部</li><li><strong>物理层传输</strong>：编码为比特流发送</li><li><strong>逐跳转发</strong>：每个路由器解封到网络层 → 查路由表 → 重新封装 → 转发</li><li><strong>服务器处理</strong>：解封到应用层 → 处理请求 → 构造 HTTP 响应</li><li><strong>返回响应</strong>：按相反过程逐层封装返回</li><li><strong>浏览器渲染</strong>：解析 HTML/CSS/JS → 显示页面</li></ol><hr><div class="important custom-block github-alert"><p class="custom-block-title">本章考频总结</p><p></p><ul><li>各协议端口号与传输层协议 ★★★★★</li><li>DNS 查询过程（递归/迭代）★★★★</li><li>HTTP 持久/非持久连接 ★★★★</li><li>电子邮件发送过程（SMTP/POP3）★★★★</li><li>HTTP 状态码 ★★★</li><li>输入 URL 后的完整过程 ★★★</li></ul></div>`,42)])])}const u=s(l,[["render",e]]);export{c as __pageData,u as default};
